import {comparisonPreview} from './comparison-preview.js';
import {skyMarkup,mountSky} from './sky.js';
import {MIRA_CELL} from './sky-model.js';
import { STATUS, MIRA, regionBounds, cellBounds, regionName, cellName, key, readState, sampleStatus, regionStatus, parseSelection, nextRegion } from './model.js';
import { drawAtlas } from './atlas.js';
const app = document.querySelector('#app');
let state = readState(), animation, reviewTimer, resizeTimer, reviewRun = null;
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repeats = (n,fn) => Array.from({length:n},(_,i)=>fn(i)).join('');
const real = (r,c) => r===MIRA.region && c===MIRA.cell;
const urlFor = (r=null,c=null) => '/explore/'+(r===null?'':`?region=${r}`+(c===null?'':`&cell=${c}`));
const shownStatus = (r,c) => reviewRun?.r===r && reviewRun?.c===c ? 'working' : sampleStatus(r,c,state.reviews);
const statusIcon = s => `<span class="status-icon" style="--status:${STATUS[s].color}" aria-hidden="true">${STATUS[s].icon}</span>`;
function save(){try{localStorage.setItem('sate-prototype-v1',JSON.stringify(state));return true;}catch{toast('Browser storage is unavailable. Changes last for this visit.');return false;}}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function header(path){return `<header class="site-header"><a class="brand" href="/" aria-label="SATE home"><span class="brand-mark" aria-hidden="true">${repeats(9,()=>'<i></i>')}</span>SATE</a><nav class="header-nav" aria-label="Main navigation">${[['/explore/','Explore'],['/contribute/','Contribute']].map(([p,n])=>`<a href="${p}" ${path===p?'class="active" aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="header-end"><button class="theme-switch" type="button" role="switch" aria-label="Dark mode" aria-checked="${document.documentElement.dataset.theme==='dark'}" title="Toggle dark mode"><svg class="theme-moon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.5 14.5A8.5 8.5 0 0 1 9.5 3.5a8.5 8.5 0 1 0 11 11Z"/></svg><span class="theme-switch-track" aria-hidden="true"><i></i></span></button><a class="nav-cta" href="/explore/">Enter the atlas ${arrow}</a></div></header>`;}
function footer(){return `<footer class="site-footer"><a class="footer-brand" href="/">SATE</a><span>SATE helps you explore telescope images and compare observations of the same sky region.</span><div class="footer-links"><a href="/about/">About, data &amp; sources</a></div></footer>`;}
function navigate(url,{replace=false}={}){clearInterval(animation);animation=null;(replace?history.replaceState:history.pushState).call(history,{},'',url);render();window.scrollTo(0,0);}
function landing(){return `<main id="main"><section class="hero hero-photo"><img class="hero-background" src="/assets/carina-nebula-hero.png" alt="" width="1280" height="741" fetchpriority="high"><div class="hero-inner shell"><div class="hero-copy"><h1>Help find objects<br>in space</h1><p>Explore telescope images, select a region of the sky, and compare observations to see how objects change over time and help find objects.</p><div class="hero-actions"><a class="button lime button-large" href="/explore/">Open sky map ${arrow}</a><a class="button outline button-large" href="/contribute/">Lend computing power ${arrow}</a></div></div></div><a class="hero-image-credit" href="https://science.nasa.gov/asset/webb/cosmic-cliffs-in-the-carina-nebula-nircam-image/" target="_blank" rel="noreferrer">Webb · Cosmic Cliffs<br><span>Image: NASA, ESA, CSA, STScI ↗</span></a></section><div class="shell"><div class="hero-bottom"><span><i class="dot"></i> PUBLIC TELESCOPE DATA</span><span>EXPLORE REGIONS. COMPARE OBSERVATIONS.</span><a href="/about/">ABOUT THIS PROTOTYPE ↗</a></div></div>${comparisonPreview()}<section class="shell participation"><div><h2 class="section-title">Help analyse<br>telescope images.</h2><p class="section-copy">Explore real observations through the sky map, then learn how AI analysis and computing contributions could help investigate changes.</p><a class="text-link" href="/contribute/">Find your way to help ${arrow}</a></div><div class="participation-list"><a href="/contribute/" class="contribution-line contribution-photo ai-photo"><img class="contribution-image" src="/assets/spherex-orbit-card.jpg" alt="" width="1920" height="1080" loading="lazy"><div><h3>Bring your AI</h3><p>Give an assistant a small investigation. Compare images, check sources, bring back the evidence.</p></div>${arrow}</a><a href="/explore/" class="contribution-line contribution-photo observation-action"><img class="contribution-image" src="/assets/spherex-observation-card.jpg" alt="" width="1024" height="575" loading="lazy"><div><h3>See real observations manually through sky map</h3><p>Explore telescope images, select a sky region and view it at different wavelengths.</p></div>${arrow}</a><a class="contribution-credits" href="/about/">Images: NASA/JPL-Caltech</a></div></section></main>${footer()}`;}
function contribute(){return `<main id="main" class="contribute-page"><section class="contribute-hero" aria-labelledby="contribute-heading"><img class="contribute-hero-image" src="/assets/spherex-orbit-card.jpg" alt="" width="1920" height="1080" fetchpriority="high"><div class="shell"><div class="page-heading"><h1 id="contribute-heading">Help analyse changes<br>in telescope images.</h1><p>Comparing observations can reveal objects that brighten, fade or move. The aim is to let volunteers help investigate those changes using AI assistants and spare computing power.</p></div></div><a class="contribute-hero-credit" href="https://science.nasa.gov/photojournal/spherex-in-orbit-artists-concept/" target="_blank" rel="noreferrer">SPHEREx · Artist’s concept<br>NASA/JPL-Caltech ↗</a></section><div class="shell contribute-layout"><div class="contribute-explanation"><section aria-labelledby="ai-purpose"><span class="contribute-status">Planned feature</span><h2 id="ai-purpose">Use AI to investigate a sky region</h2><p>An AI assistant could compare images of the same region, check observation dates and source records, and summarise possible changes with supporting evidence. This would help people decide which objects deserve a closer look.</p><p class="contribute-availability">AI assistants cannot be connected here yet, and this page does not use your AI account or allowance.</p></section><section aria-labelledby="compute-purpose"><span class="contribute-status">Planned feature</span><h2 id="compute-purpose">Contribute computing power to image analysis</h2><p>Preparing telescope images for comparison takes processing time. The proposed feature would use spare computing capacity to align images and compare observations across a selected region.</p><p class="contribute-availability">Background computing is not available yet. Visiting this page does not start processing jobs.</p></section></div><aside class="contribute-summary" aria-labelledby="contribute-start"><h2 id="contribute-start">Explore real observations in the sky map</h2><p>Open the sky map and select a region to inspect. Zoom in to see more detail, then use the wavelength control to view the same region in different infrared bands.</p><p>The map combines observations taken at different times. Use it to explore regions and wavelengths; it is not a time sequence.</p><a class="button full-width" href="/explore/">Open sky map ${arrow}</a></aside></div></main>${footer()}`;}
function about(){return `<main id="main" class="shell"><div class="page-heading"><div class="eyebrow">About SATE</div><h1>A shared search,<br>starting small.</h1><p>Explore the sky. Choose a square. Bring back something worth a closer look.</p></div><div class="legal-content"><h2>This is an early prototype</h2><p>The atlas, cell selection and sample reviews demonstrate the idea. Sample activity is stored only in your browser. No AI allowance is used and no background computation runs.</p><p>The broader aim is to let volunteers contribute bounded investigations and spare computing power to a search for changing and moving objects, including possible distant worlds. A candidate would need independent confirmation.</p><h2>What’s real here</h2><p>The example thumbnails in the sky map and homepage illustration use SPHEREx observations with <a href="/assets/mira.json" download="sate-spherex-observation.json">downloadable source records</a>. It is a known Mira variable, J1502099+593125. The example covers a 60-arcsecond field, not an entire atlas cell.</p><p>The interactive atlas uses the <a href="https://irsa.ipac.caltech.edu/data/hips/SPHEREx/spherex_allsky_cube/properties" target="_blank" rel="noreferrer">SPHEREx DR1 all-sky image cube</a>. Its 102 wavelength channels combine observations across time. The equal-area HEALPix grid has 3,145,728 search cells with an equivalent-square width of 6.87 arcminutes. These are investigation areas, not instrument footprints. The homepage background shows Webb’s Cosmic Cliffs in the Carina Nebula, credited to NASA, ESA, CSA and STScI.</p><h2>Reading the colours</h2><p>Grey: not reviewed. Blue: in progress. Green: reviewed with no unexplained candidate in the selected observations. Amber: needs another look. New data can reopen a review. Missing data should never count as a completed search.</p><h2>Your browser, your demo</h2><p>Sample review reports stay in local browser storage. They are not shared with other visitors.</p><button class="button outline small" data-action="reset">Reset my demo activity</button><h2 id="image-credits">Image and data credits</h2><p>The contribution cards use <a href="https://science.nasa.gov/photojournal/spherex-in-orbit-artists-concept/" target="_blank" rel="noreferrer">SPHEREx in Orbit (artist’s concept)</a> and <a href="https://www.nasa.gov/missions/spherex/nasas-spherex-space-telescope-begins-capturing-entire-sky/" target="_blank" rel="noreferrer">a SPHEREx infrared image of stars and dust at 3.29 microns</a>, both credited to NASA/JPL-Caltech. The star-and-dust background illustrates the mission’s observations. The small example thumbnails show a separate Mira variable-star field.</p><p>SPHEREx mission data served by NASA/IPAC IRSA. Catalog annotations retain their source IDs in the downloadable observation record. Star-map data: D3-Celestial, © Olaf Frohn and contributors, <a href="/assets/LICENSE">BSD 3-Clause licence</a>.</p></div></main>${footer()}`;}
function paint(){const hero=document.querySelector('#hero-canvas');if(hero)drawAtlas(hero,{polar:true});const sky=document.querySelector('#sky-canvas');if(sky){const{region}=parseSelection(location.search);drawAtlas(sky,region===null?{}:{bounds:regionBounds(region)});}}
let skyCleanup,renderToken=0;
function render(){const token=++renderToken;skyCleanup?.();skyCleanup=null;let path=location.pathname.replace(/\/+$/,'')+'/';if(path==='//')path='/';if(path==='/explore/'&&(new URLSearchParams(location.search).has('assign')||new URLSearchParams(location.search).has('region'))){history.replaceState({},'','/explore/?hpx='+MIRA_CELL+'&order=9');}document.body.classList.toggle('explorer-page',path==='/explore/');const pages={'/':landing,'/explore/':skyMarkup,'/contribute/':contribute,'/about/':about};app.innerHTML=header(path)+(pages[path]?pages[path]():`<main id="main" class="not-found"><h1>A little off course.</h1><a class="button" href="/">Return home ${arrow}</a></main>`);document.title=({'/':'Explore and compare space observations','/explore/':'Sky atlas','/contribute/':'Contribute','/about/':'About this prototype'}[path]||'Not found')+' — SATE';paint();if(path==='/explore/')mountSky().then(clean=>{if(token===renderToken)skyCleanup=clean;else clean?.();});}
app.addEventListener('click',async e=>{const link=e.target.closest('a');if(link){if(link.hasAttribute('download')||link.target||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const u=new URL(link.href);if(u.origin===location.origin&&!u.pathname.startsWith('/assets/')){if(location.pathname.startsWith('/explore')||u.pathname.startsWith('/explore'))return;e.preventDefault();navigate(u.pathname+u.search+u.hash);}return;}const button=e.target.closest('button');if(button?.classList.contains('theme-switch')){window.sateTheme.toggle();return;}if(!button||button.closest('[data-sky]'))return;if(button.dataset.selectRegion!==undefined){navigate('/explore/?inspect='+Number(button.dataset.selectRegion));return;}if(button.dataset.region!==undefined){navigate(urlFor(Number(button.dataset.region)));return;}if(button.dataset.cell!==undefined){const{region}=parseSelection(location.search);navigate(urlFor(region,Number(button.dataset.cell)));return;}switch(button.dataset.action){case'all':navigate(urlFor());break;case'example-cell':navigate('/explore/?inspect='+MIRA.region);break;case'auto':{const n=nextRegion(state.reviews);if(n)navigate(urlFor(n.region,n.cell));else toast('All demo cells have been assigned. Reset the demo to start again.');break;}case'cancel':clearInterval(reviewTimer);reviewRun=null;render();break;case'copy':try{await navigator.clipboard.writeText(location.href);toast('Cell link copied.');}catch{toast('Copy the cell URL from your address bar.');}break;case'reset':localStorage.removeItem('sate-healpix-reviews-v1');clearInterval(reviewTimer);reviewRun=null;state={reviews:{},preferences:{ai:true,compute:false,batch:'5',power:'light'}};save();toast('Demo activity reset.');break;}});
app.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='coordinate-form'){const ra=Number(f.get('ra')),dec=Number(f.get('dec'));if(!Number.isFinite(ra)||ra<0||ra>=360||!Number.isFinite(dec)||dec< -90||dec>90){document.querySelector('#coord-error').textContent='Use RA 0–360° and Dec −90–90°.';return;}const col=Math.min(11,Math.floor((360-ra)/30)),row=Math.min(5,Math.floor((90-dec)/30)),r=row*12+col,b=regionBounds(r),c=Math.min(2,Math.floor((b.north-dec)/10))*3+Math.min(2,Math.floor((b.west-ra)/10));navigate(urlFor(r,c));}});
app.addEventListener('keydown',e=>{const b=e.target.closest('.map-cell,.nine-grid button');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const list=[...b.parentNode.children],cols=b.parentNode.classList.contains('subgrid')||b.parentNode.classList.contains('nine-grid')?3:12,index=list.indexOf(b),move={ArrowLeft:-1,ArrowRight:1,ArrowUp:-cols,ArrowDown:cols}[e.key];e.preventDefault();const next=list[Math.max(0,Math.min(list.length-1,index+move))];b.tabIndex=-1;next.tabIndex=0;next.focus();});
window.addEventListener('popstate',()=>{clearInterval(animation);animation=null;render();});window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(paint,120);});render();
